def transform(grid):
    """Encode each 3x3 cell of the 12x12 canvas by its non-background color."""
    out = []
    for br in range(0, len(grid), 3):
        row = []
        for bc in range(0, len(grid[0]), 3):
            colors = {grid[r][c] for r in range(br, min(br + 3, len(grid)))
                      for c in range(bc, min(bc + 3, len(grid[0])))
                      if grid[r][c] not in (0, 5)}
            row.append(next(iter(colors)) if colors else 0)
        out.append(row)
    return out
